from decimal import Decimal, ROUND_HALF_UP


def text(value):
    """Anything a source or an extractor gives us, as a comparable string."""
    return "" if value is None else str(value).strip()


def empty(value):
    return text(value) == ""


def num(value):
    """A printed amount as a Decimal, accepting a comma as decimal separator."""
    s = text(value).replace(" ", "")
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        s = s.replace(",", ".")
    return Decimal(s)


def cents(value):
    return int((Decimal(str(value)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def fires(reason):
    return {"fires": True, "reason": reason}


def passes():
    return {"fires": False, "reason": ""}


def evaluate(instance, sources, others):
    """The printed VAT must be base * vat_rate / 100 within one cent."""
    base = instance.get("base")
    rate = instance.get("vat_rate")
    vat = instance.get("vat_amount")
    if empty(base) or empty(rate) or empty(vat):
        return passes()
    expected = num(base) * num(rate) / Decimal(100)
    if abs(cents(num(vat)) - cents(expected)) <= 1:
        return passes()
    return fires(
        "VAT " + text(vat) + " != " + text(base) + " * " + text(rate) + " / 100"
    )

